<?php
require_once __DIR__.'/../config/auth.php';require_role('owner');$pageTitle='Akun Kasir';$message='';$error='';
if($_SERVER['REQUEST_METHOD']==='POST'){csrf_check();$action=(string)($_POST['action']??'');try{if($action==='create'){$nama=clean_text((string)($_POST['nama']??''),100);$username=trim((string)($_POST['username']??''));$password=(string)($_POST['password']??'');if($nama===''||!preg_match('/^[a-zA-Z0-9_.-]{3,50}$/',$username))throw new RuntimeException('nama wajib diisi dan username 3–50 karakter (huruf, angka, titik, garis bawah, atau minus).');if(strlen($password)<10)throw new RuntimeException('password minimal 10 karakter.');$st=$pdo->prepare("INSERT INTO users (nama,username,password_hash,role,is_active) VALUES (?,?,?,'kasir',1)");$st->execute([$nama,$username,password_hash($password,PASSWORD_DEFAULT)]);log_activity('create_cashier',$username);$message='akun kasir dibuat.';}elseif($action==='toggle'){$id=(int)$_POST['id'];$pdo->prepare("UPDATE users SET is_active=IF(is_active=1,0,1) WHERE id=? AND role='kasir'")->execute([$id]);log_activity('toggle_cashier','ID '.$id);$message='status akun kasir diperbarui.';}elseif($action==='reset'){$id=(int)$_POST['id'];$pw=(string)($_POST['new_password']??'');if(strlen($pw)<10)throw new RuntimeException('password baru minimal 10 karakter.');$st=$pdo->prepare("UPDATE users SET password_hash=? WHERE id=? AND role='kasir'");$st->execute([password_hash($pw,PASSWORD_DEFAULT),$id]);log_activity('reset_cashier_password','ID '.$id);$message='password berhasil direset. berikan password baru secara aman.';}}catch(Throwable $e){$error=$e instanceof RuntimeException?$e->getMessage():'username sudah digunakan atau data tidak valid.';}}
$users=dbq("SELECT id,nama,username,is_active,created_at FROM users WHERE role='kasir' ORDER BY created_at DESC")->fetchAll();require __DIR__.'/../includes/admin-header.php'; ?>
<?php if($message):?><div class="flash flash-ok"><?= h($message) ?></div><?php endif;?><?php if($error):?><div class="flash flash-error"><?= h($error) ?></div><?php endif;?><div class="grid xl:grid-cols-[380px_1fr] gap-5 items-start"><section class="card p-5"><h2 class="font-serif text-2xl">Buat akun kasir</h2><p class="text-xs text-coffee/55 mt-2">akun owner tidak dapat dibuat dari halaman ini.</p><form method="post" class="space-y-4 mt-5"><input type="hidden" name="_csrf" value="<?= h(csrf_token()) ?>"><input type="hidden" name="action" value="create"><div><label class="field-label">Nama lengkap</label><input class="field" name="nama" maxlength="100" required></div><div><label class="field-label">Username</label><input class="field" name="username" minlength="3" maxlength="50" required></div><div><label class="field-label">Password awal</label><input class="field" name="password" type="password" minlength="10" required><p class="text-xs text-coffee/50 mt-1">minimal 10 karakter.</p></div><button class="btn btn-coffee w-full">Buat akun kasir</button></form></section><section class="card p-5"><h2 class="font-serif text-2xl">Akun kasir</h2><div class="table-wrap mt-4"><table class="admin-table"><thead><tr><th>Nama / username</th><th>Status</th><th>Dibuat</th><th>Kelola</th></tr></thead><tbody><?php foreach($users as $u):?><tr><td><b><?= h($u['nama']) ?></b><span class="block text-xs text-coffee/55">@<?= h($u['username']) ?></span></td><td><span class="status-pill <?= $u['is_active']?'status-green':'status-red' ?>"><?= $u['is_active']?'Aktif':'Nonaktif' ?></span></td><td><?= h(date('d M Y',strtotime($u['created_at']))) ?></td><td><div class="flex flex-col gap-3"><form method="post"><input type="hidden" name="_csrf" value="<?= h(csrf_token()) ?>"><input type="hidden" name="action" value="toggle"><input type="hidden" name="id" value="<?= (int)$u['id'] ?>"><button class="underline text-xs"><?= $u['is_active']?'Nonaktifkan':'Aktifkan' ?></button></form><form method="post" class="flex flex-wrap gap-2"><input type="hidden" name="_csrf" value="<?= h(csrf_token()) ?>"><input type="hidden" name="action" value="reset"><input type="hidden" name="id" value="<?= (int)$u['id'] ?>"><input class="field !w-36 !p-2 !text-xs" type="password" name="new_password" minlength="10" placeholder="Password baru" required><button class="btn btn-light !p-2 !text-xs">Reset</button></form></div></td></tr><?php endforeach;?></tbody></table></div></section></div><?php require __DIR__.'/../includes/admin-footer.php'; ?>
